(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["principles-of-diagnostic-medicine-i-exam-2"]={"title":"Principles of Diagnostic Medicine I Exam 2","sections":[{"id":"scope","title":"How This Exam Is Written","style":"--acc:#a1363a;--acc-bg:#f2e3e3;--acc-zebra:#f8f1f1;--acc-ink:#7e2a2d"},{"id":"action-potential","title":"Action Potential & Refractory Periods","style":"--acc:#7a2a2e;--acc-bg:#ece1e2;--acc-zebra:#f6f0f0;--acc-ink:#5f2124"},{"id":"conduction","title":"Conduction System","style":"--acc:#8f4a3a;--acc-bg:#efe6e3;--acc-zebra:#f7f2f1;--acc-ink:#703a2d"},{"id":"paper-leads","title":"Paper, Leads & Rate","style":"--acc:#2b6f86;--acc-bg:#e1ebee;--acc-zebra:#f0f5f7;--acc-ink:#225769"},{"id":"intervals","title":"Waves & Intervals","style":"--acc:#1f5566;--acc-bg:#e0e7ea;--acc-zebra:#eff3f4;--acc-ink:#184250"},{"id":"cxr","title":"Chest Radiograph & Cardiothoracic Ratio","style":"--acc:#7a4d1f;--acc-bg:#ece6e0;--acc-zebra:#f6f3ef;--acc-ink:#5f3c18"},{"id":"echo-stress","title":"Echocardiography & Stress Testing","style":"--acc:#8a5a24;--acc-bg:#efe8e0;--acc-zebra:#f7f3f0;--acc-ink:#6c461c"},{"id":"ct-mri-nuclear","title":"Nuclear, CT (Computed Tomography) & MRI (Magnetic Resonance Imaging)","style":"--acc:#2b6f86;--acc-bg:#e1ebee;--acc-zebra:#f0f5f7;--acc-ink:#225769"},{"id":"invasive","title":"Angiography, Catheterization & Vascular Ultrasound","style":"--acc:#1f5566;--acc-bg:#e0e7ea;--acc-zebra:#eff3f4;--acc-ink:#184250"},{"id":"biomarkers","title":"The Four Cardiac Biomarkers","style":"--acc:#a1363a;--acc-bg:#f2e3e3;--acc-zebra:#f8f1f1;--acc-ink:#7e2a2d"},{"id":"order-biomarkers","title":"When to Order Which","style":"--acc:#7a2a2e;--acc-bg:#ece1e2;--acc-zebra:#f6f0f0;--acc-ink:#5f2124"},{"id":"lipoproteins","title":"Lipoproteins & Apolipoproteins","style":"--acc:#7a4d1f;--acc-bg:#ece6e0;--acc-zebra:#f6f3ef;--acc-ink:#5f3c18"},{"id":"lipid-panel","title":"Ordering & Reading a Lipid Panel","style":"--acc:#8a5a24;--acc-bg:#efe8e0;--acc-zebra:#f7f3f0;--acc-ink:#6c461c"},{"id":"risk","title":"Risk Assessment","style":"--acc:#2b6f86;--acc-bg:#e1ebee;--acc-zebra:#f0f5f7;--acc-ink:#225769"}],"rows":[{"t":"Reference ranges are GIVEN","d":"“I'm not going to just throw a random number at you” — a troponin, triglyceride or C-reactive protein in a stem comes with the limit that reads it. Learn what a value MEANS.","s":0},{"t":"Name the rhythm","d":"Electrocardiography is the one place where naming the finding is fair game. Lecture 7 is the toolkit: paper, leads, rate, intervals.","s":0},{"t":"Next-best-test","d":"“What would be the next test that you would order?” Know what each imaging study can and cannot show, and what to do when one is equivocal.","s":0},{"t":"Not examined (said out loud)","d":"Ion-channel subtypes (but which ion moves in each phase IS). Bazett's formula (“I will never ask you about the formula”). The bifascicular-block aside. The order of the exercise-endpoint chart and the treadmill protocol tables.","s":0},{"t":"Four cell properties","d":"AUTOMATICITY (makes its own impulse) · EXCITABILITY (responds to one) · CONTRACTILITY · CONDUCTIVITY (passes it on).","s":1},{"t":"Phase order","d":"4 → 0 → 1 → 2 → 3. “You need to know what happens in each phase.”","s":1},{"t":"Phase 4 / 0","d":"4 = rest (diastole), −90 mV, potassium inside. 0 = upstroke: FAST SODIUM CHANNELS open, sodium rushes in.","s":1},{"t":"Phase 1 / 2 / 3","d":"1 = early repolarization (sodium closes). 2 = PLATEAU: CALCIUM IN causes contraction, balanced by potassium OUT. 3 = rapid repolarization: calcium closes, potassium out, back to −90 mV. (Slide text says potassium “in”; its own figure shows efflux.)","s":1},{"t":"Depolarization vs repolarization","d":"Depolarization = membrane LESS negative, ACTIVATION, PRECEDES contraction. Repolarization = return toward rest, RECOVERY.","s":1},{"t":"Absolute refractory","d":"Will NOT respond. Phase 0 to MID phase 3, about 180 ms.","s":1},{"t":"Relative refractory","d":"WILL respond but fragile. Mid phase 3 to END of phase 3. The T-WAVE PEAK divides the two. Basis of R on T, P on T and the danger of a long QTc.","s":1},{"t":"Sinoatrial node","d":"Main pacemaker, upper right atrium below the vena cava. 60–100 per minute. Three internodal tracts; most people use the superior anterior (FAST) tract.","s":2},{"t":"Atrioventricular node","d":"Near the coronary sinus. PAUSES and AMPLIFIES the signal; back-up pacemaker. 40–60 per minute.","s":2},{"t":"Bundle of His","d":"The ONLY electrical path from atria to ventricles in a normal heart, through the nonconductive atrioventricular septum.","s":2},{"t":"Bundle branches","d":"Left splits into THREE fascicles (posterior, septal, anterior). Right is MUCH LONGER than the left. Bifascicular block is NOT a left bundle branch block.","s":2},{"t":"Purkinje network","d":"Third pacemaker, 20–40 per minute; fastest conduction of all.","s":2},{"t":"Cardiac vector","d":"Direction and strength of current; true pathway is LEFT AND DOWN toward the anterior chest.","s":2},{"t":"Time","d":"Small box 0.04 s · large box 0.2 s · 5 large boxes = 1 s. Strips are 3 or 6 seconds.","s":3},{"t":"Voltage","d":"Small box 1 mm = 0.1 mV; 10 mm (two large boxes) = 1 mV.","s":3},{"t":"Bipolar vs unipolar","d":"BIPOLAR = two electrodes: I, II, III (Einthoven's triangle). UNIPOLAR = one electrode: aVR, aVL, aVF (augmented) and V1–V6.","s":3},{"t":"10 wires, 12 leads","d":"Four limb electrodes make SIX hexaxial leads (I, II, III, aVR, aVL, aVF, used for axis); plus six chest leads. Placement must be MEMORIZED.","s":3},{"t":"Lead II","d":"Best view of the heart's vector, so it is the RHYTHM lead.","s":3},{"t":"Which leads look where","d":"Inferior II, III, aVF · septum V1–V2 · anterior V3–V4 · lateral I, aVL, V5–V6. Anteroseptal infarction shows in V1–V4 (both supplied by the left anterior descending artery).","s":3},{"t":"Cannot tell you","d":"Hemodynamic status, cardiac output, or WHETHER THERE IS A PULSE.","s":3},{"t":"Rate methods","d":"REGULAR rhythms only. 6-second: QRS count × 10 (P count × 10 for atrial). 300 method: heavy lines count 300, 150, 100, 75, 60, 50.","s":3},{"t":"P wave","d":"Atrial depolarization; under 0.12 s; upright in lead II.","s":4},{"t":"PR interval","d":"0.12–0.20 s (3–5 small boxes): atria, atrioventricular node delay, His-Purkinje.","s":4},{"t":"QRS","d":"Ventricular depolarization; under 0.12 s, narrow and sharp. Q = septum, R = anterior left ventricle, S = lateral left ventricle.","s":4},{"t":"J point & ST","d":"J point = end of QRS, start of ST; at baseline (1 mm variance). “Very important that you know how to identify the J point.” ST = ventricles holding contraction; at baseline.","s":4},{"t":"T wave","d":"Ventricular repolarization, 0.16–0.25 s.","s":4},{"t":"QT / QTc","d":"Start of QRS to end of T. 350–450 ms males, 360–460 ms females. QTc = rate-corrected; above 450 (460) to 500 = borderline; ABOVE 500 ms = HIGH-RISK.","s":4},{"t":"U wave & TP","d":"U: after T, same direction, best V2–V3; prominent in hypokalemia, hypercalcemia, long QT, post-infarction. TP segment = best place to judge the isoelectric line.","s":4},{"t":"The system","d":"Rhythm → rate → P waves → P for every QRS → QRS width → PR → ST → T → QTc → extra waves or beats → voltage.","s":4},{"t":"Its standing","d":"NOT the primary modality for function or detailed anatomy, but gives clues when obtained: silhouette, great vessels, pulmonary vasculature, lungs and pleura.","s":5},{"t":"Right border","d":"Superior vena cava → right atrium.","s":5},{"t":"Left border","d":"Aortic knuckle → main pulmonary artery → left atrial appendage → left ventricle (forms the apex).","s":5},{"t":"Cardiac findings","d":"Pulmonary edema · pleural effusion · cardiomegaly · CEPHALIZATION · great vessel, valve or pericardial calcification · tension physiology.","s":5},{"t":"Cephalization","d":"Upper-lobe vessels bigger than lower. Heart failure or pulmonary hypertension.","s":5},{"t":"Cardiothoracic ratio","d":"Widest heart ÷ widest INTERNAL thorax. Normal 0.42–0.5; ABOVE 0.5 on a PROPER POSTEROANTERIOR film suggests cardiomegaly.","s":5},{"t":"Echo shows","d":"STRUCTURE AND FUNCTION: chambers, walls, ejection fraction, Doppler flow, valves, shunts, pressures.","s":6},{"t":"TTE (transthoracic echocardiogram)","d":"Most common, bedside, noninvasive. Poor for the POSTERIOR heart.","s":6},{"t":"TEE (transesophageal echocardiogram)","d":"Probe in the esophagus. Aorta and great vessels, myxoma, prosthetic valves, VEGETATIONS, cerebral ischemia, LEFT ATRIAL APPENDAGE THROMBUS.","s":6},{"t":"TEE contraindications","d":"Anything the probe can injure or an airway you cannot protect: esophageal stricture, malignancy, bleeding varices; dysphagia; ZENKER'S DIVERTICULUM; cervical arthritis; sleep apnea; uncooperative patient.","s":6},{"t":"Valid exercise test","d":"At least 85% of predicted maximum; predicted maximum = 220 − AGE. Under 85% cannot exclude ischemia.","s":6},{"t":"Exercise test reads","d":"Ischemia indirectly: ST DEPRESSION or new premature ventricular contractions. Bruce protocol; bicycle preferred.","s":6},{"t":"Echo stress","d":"Can exercise but baseline ST-T changes. Look for NEW WALL-MOTION abnormality right after exercise.","s":6},{"t":"Pharmacologic stress","d":"Cannot exercise. ADENOSINE or DIPYRIDAMOLE vasodilate; DOBUTAMINE raises workload.","s":6},{"t":"Nuclear perfusion","d":"Tracer at rest and after stress. Less uptake after stress = ischemia; NO uptake = dead tissue (VIABILITY). More accurate than standard or echo stress.","s":7},{"t":"Coronary CT angiography","d":"Presence and distribution of coronary disease; detect or exclude stenosis or plaque; EQUIVOCAL OR NON-DIAGNOSTIC STRESS TEST → next best step.","s":7},{"t":"Cardiac CT","d":"Non-contrast = CALCIUM SCORING. Metoprolol slows the heart, nitroglycerin dilates, electrocardiogram gating.","s":7},{"t":"CT limits","d":"ANATOMY ONLY, NOT FUNCTION. Radiation, contrast, rate dependent, BLOOMING artifact overstates calcium.","s":7},{"t":"Cardiac magnetic resonance","d":"Anatomy, function, viability, perfusion, INFLAMMATION — no ionizing radiation or iodinated contrast. ECHO FIRST. Aorta, congenital disease, cardiomyopathies, myocarditis, sarcoid.","s":7},{"t":"Magnetic resonance limits","d":"Implants (aneurysm clips, some pacemakers), long acquisition, claustrophobia. Titanium is acceptable.","s":7},{"t":"GOLD STANDARD","d":"Coronary angiography for coronary disease — “a high-miss last year.” Can treat in the same sitting (balloon, stent).","s":8},{"t":"Why go to the catheter","d":"Noninvasive tests say IF disease is there; angiography says HOW MUCH, and intervention is by percentage. Positive CT angiogram with left anterior descending disease → catheter.","s":8},{"t":"Left vs right heart cath","d":"LEFT (artery) = CORONARY ARTERIES. RIGHT (vein) = PULMONARY HYPERTENSION.","s":8},{"t":"Complications","d":"Access-site HEMATOMA and PSEUDOANEURYSM (pulsatile, communicates with the artery). Always check the site.","s":8},{"t":"Electrophysiology testing","d":"Catheters via a vein into the right heart provoke and locate an arrhythmia; ablation can treat it.","s":8},{"t":"Vascular ultrasound","d":"Veins COLLAPSE, arteries PULSATE on compression. Deep vein thrombosis, carotid, peripheral arterial disease, aneurysm, venous insufficiency. No radiation; HIGHLY OPERATOR DEPENDENT.","s":8},{"t":"The frame","d":"Biomarkers: “is there ACUTE cardiac injury or stress?” Lipids: “what is the LONG-TERM atherosclerotic risk?”","s":9},{"t":"Troponin","d":"Myocyte INJURY. Marker of choice. Infarction = above the 99th PERCENTILE upper reference limit + ischemic symptoms. Sex-specific limits.","s":9},{"t":"Troponin subunits","d":"I = CARDIAC SPECIFIC. T = mostly cardiac, trace skeletal. C = NOT useful.","s":9},{"t":"High-sensitivity troponin","d":"The ASSAY, not a subunit. Draw at 0 and 1–2 HOURS; up to 90 minutes earlier. Pitfall: measurable in healthy people.","s":9},{"t":"Injury vs infarction","d":"Injury = any elevation. Infarction = injury + ISCHEMIA + RISING/FALLING pattern. Chronically raised in kidney disease, heart failure, structural disease — never read one value alone.","s":9},{"t":"Creatine kinase","d":"Skeletal muscle: RHABDOMYOLYSIS, STATIN MYOPATHY. Low cardiac specificity. Creatine kinase-MB, myoglobin, lactate dehydrogenase are RETIRED for infarction.","s":9},{"t":"BNP (B-type natriuretic peptide)","d":"STRETCH, not injury. Rule-out of new heart failure; monitor, guide, prognosis. Rises with age, female sex, kidney disease; FALSELY LOW IN OBESITY. Not stand-alone.","s":9},{"t":"hs-CRP (high-sensitivity C-reactive protein)","d":"Inflammation; a RISK ENHANCER, never an acute test. Non-specific. Highest in bacterial infection. Lowered by statins, NSAIDs (nonsteroidal anti-inflammatory drugs), GLP-1 (glucagon-like peptide-1) agonists, lifestyle. In the Reynolds Risk Score.","s":9},{"t":"Chest pain","d":"SERIAL HIGH-SENSITIVITY TROPONIN, first-line; first value is also prognostic.","s":10},{"t":"Dyspnea / heart failure","d":"BNP (B-type natriuretic peptide) or NT-proBNP (N-terminal pro B-type natriuretic peptide); also prognostic after acute coronary syndrome.","s":10},{"t":"Muscle pain on a statin","d":"CREATINE KINASE, not troponin.","s":10},{"t":"Risk refinement","d":"hs-CRP (high-sensitivity C-reactive protein) in select primary prevention.","s":10},{"t":"Do NOT order","d":"Routine natriuretic peptides in healthy people; creatine kinase-MB or myoglobin for infarction.","s":10},{"t":"Troponin, other uses","d":"Unstable angina (normal = no injury) · reinfarction · infarct size (late 4-week value INVERSELY related to ejection fraction) · procedural: type 4a more than 5×, type 5 (bypass) more than 10× the 99th percentile limit.","s":10},{"t":"Why particles","d":"Cholesterol and triglycerides are INSOLUBLE. Lipoprotein = lipid core + phospholipid shell + apolipoproteins.","s":11},{"t":"One apoB particle","d":"Liver VLDL (very low-density lipoprotein) → lipoprotein lipase strips triglyceride → remnant → LDL (low-density lipoprotein). Under ~70 nm can be TRAPPED in the artery wall.","s":11},{"t":"ApoB-48 / ApoB-100","d":"B-48 = intestine, CHYLOMICRONS. B-100 = liver: very low-, intermediate-, low-density lipoprotein and lipoprotein(a). NOT in HDL (high-density lipoprotein).","s":11},{"t":"ApoA-I / ApoE","d":"A-I = ALL HDL (high-density lipoprotein). E = triglyceride CLEARANCE. C-III and A-V regulate triglyceride metabolism.","s":11},{"t":"LDL vs HDL","d":"LDL (low-density lipoprotein) = PRINCIPAL DRIVER, log-linear with risk. HDL = REVERSE CHOLESTEROL TRANSPORT. Remnants carry RESIDUAL risk.","s":11},{"t":"Lipoprotein(a)","d":"LDL-like + apo(a) on apoB-100. Over 90% GENETIC, stable, NO FASTING, measure ONCE in all adults; repeat after menopause if borderline; CASCADE test families. STATINS DO NOT LOWER IT. About 20% of people elevated.","s":11},{"t":"Measured","d":"Total cholesterol, HDL-C (high-density lipoprotein cholesterol), triglycerides.","s":12},{"t":"Calculated","d":"LDL-C (low-density lipoprotein cholesterol) — an ESTIMATE — and non-HDL-C = total cholesterol − HDL-C.","s":12},{"t":"Friedewald","d":"LDL-C = total − HDL-C − triglycerides ÷ 5. INVALID when triglycerides are 400 mg/dL or above; Martin/Hopkins or Sampson/NIH (National Institutes of Health) preferred.","s":12},{"t":"Non-HDL-C","d":"Every atherogenic apoB lipoprotein, NO added cost, BETTER predictor than LDL-C.","s":12},{"t":"No single normal","d":"LDL-C and non-HDL-C goals depend on RISK TIER; triglyceride, apoB and lipoprotein(a) thresholds are fixed. HDL-C is a MARKER, not a target.","s":12},{"t":"Triglycerides","d":"150+ = risk enhancer · 500+ = SEVERE, PANCREATITIS risk · 1000+ = extreme.","s":12},{"t":"ApoB","d":"Modifiable, repeated to monitor therapy; use with triglycerides 150+, diabetes or low LDL-C to find residual risk.","s":12},{"t":"Fasting?","d":"NONFASTING for most. Fasting with triglycerides 400+, a triglyceride disorder, or FAMILY HISTORY OF PREMATURE DISEASE or genetic dyslipidemia.","s":12},{"t":"Screening","d":"Children 9–11 (from age 2 with family history or familial hypercholesterolemia) · again at 19 · adults about EVERY 5 YEARS · on therapy recheck 4–12 WEEKS, then every 6–12 months.","s":12},{"t":"PREVENT (Predicting Risk of cardiovascular disease EVENTs)","d":"Lipids feed a 10-YEAR risk estimate, which sets treatment intensity.","s":13},{"t":"Calculate → Personalize → Reclassify","d":"Low under 3% · borderline 3 to under 5% (add RISK ENHANCERS) · intermediate 5 to under 10% · high 10% or above.","s":13},{"t":"Uncertain?","d":"At borderline or intermediate risk, a CORONARY ARTERY CALCIUM SCORE reclassifies.","s":13},{"t":"LDL-C goals","d":"Under 100 if risk under 10% · under 70 if 10%+, familial hypercholesterolemia, diabetes with risk factors, or calcium 100+ · under 55 for very-high-risk clinical disease. 190+ = statin regardless of risk.","s":13},{"t":"Elevated lipoprotein(a)","d":"Earlier, more intensive control of EVERY OTHER risk factor.","s":13}],"map":{"principles-of-diagnostic-medicine-i-exam-2-cardiac-biomarkers-lipids-quiz-version-2":[80,61,85,-1,85,72,76,77,80,87,78,66,62,-1,81,-1,88,86,79,75,59,65,84,64,66,78,71,67,65,62],"principles-of-diagnostic-medicine-i-exam-2-cardiac-biomarkers-lipids-quiz":[81,77,66,63,88,62,74,73,75,64,88,68,76,70,82,60,74,72,67,72,68,57,64,75,87,77,84,75,73,65],"principles-of-diagnostic-medicine-i-exam-2-cardiac-imaging-quiz-version-2":[40,2,39,-1,45,40,41,58,40,36,58,58,37,47,-1,49,45,58,47,48,58,-1,-1,36,51,51,41,44,49,38],"principles-of-diagnostic-medicine-i-exam-2-cardiac-imaging-quiz":[51,48,42,47,55,44,47,33,44,45,47,51,43,47,45,33,45,-1,58,57,48,35,41,48,51,38,57,37,45,48],"principles-of-diagnostic-medicine-i-exam-2-electrocardiography-quiz-version-2":[19,29,21,11,20,8,4,19,31,23,14,4,21,6,21,5,8,11,17,29,19,14,29,30,28,26,26,6,16,26],"principles-of-diagnostic-medicine-i-exam-2-electrocardiography-quiz":[7,29,15,21,24,9,26,20,12,16,25,6,6,20,10,26,1,24,13,17,8,20,31,11,-1,29,24,27,20,26]}};
